def manhattan_mst(pts):
    n=len(pts); chosen={0}; edges=[]
    while len(chosen)<n:
        opts=[]
        for i in chosen:
            for j in range(n):
                if j not in chosen:
                    d=abs(pts[i][0]-pts[j][0])+abs(pts[i][1]-pts[j][1])
                    opts.append((d,i,j))
        e=min(opts); edges.append(e); chosen.add(e[2])
    return edges
print(manhattan_mst(pts1), 'total',sum(e[0] for e in manhattan_mst(pts1)))

