def transform(grid):
    """Draw the rectangular envelope of the foreground marks and join interior aligned gaps."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    foreground_counts = Counter(value for row in grid for value in row if value != background)
    if not foreground_counts:
        return out
    marker = foreground_counts.most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    # Complete the perimeter of the foreground bounding box.
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if out[r][c] == background:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if out[r][c] == background:
                out[r][c] = 2

    # Join consecutive marks that lie strictly inside the box on the same row/column.
    for r in range(r0 + 1, r1):
        cols = [c for c in range(c0 + 1, c1) if grid[r][c] == marker]
        for left, right in zip(cols, cols[1:]):
            for c in range(left + 1, right):
                if out[r][c] == background:
                    out[r][c] = 2
    for c in range(c0 + 1, c1):
